function GlassBatchMixerMaker.update(dt) if not _G.state then return end; GlassBatchMixerMaker.dayTimer=GlassBatchMixerMaker.dayTimer+dt; if GlassBatchMixerMaker.dayTimer>=30 then GlassBatchMixerMaker.dayTimer=0; for i=#GlassBatchMixerMaker.activeMaking,1,-1 do local m=GlassBatchMixerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBatchMixerMaker.completeMaking(m); table.remove(GlassBatchMixerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBatchMixerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBatchMixerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
